import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { BrowserRouter as Router, Routes, Route, Link, useNavigate } from 'react-router-dom';

// --- COMPONENTS ---

// Navbar: Daba ghadi n-ziydou liha l-3adad dyal l-makla f-panier
const Navbar = ({ cartCount }) => (
  <nav className="bg-white shadow-sm sticky top-0 z-50 w-full border-b border-gray-100">
    <div className="w-full px-6 md:px-12"> 
      <div className="flex justify-between items-center h-20">
        <Link to="/" className="flex items-center space-x-3 group">
          <div className="bg-orange-600 p-2.5 rounded-2xl shadow-lg transform group-hover:rotate-12 transition">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 10V3L4 14h7v7l9-11h-7z" />
            </svg>
          </div>
          <div className="flex flex-col text-left">
            <span className="font-black text-2xl text-gray-900 leading-none tracking-tight">FAST<span className="text-orange-600">DÉLICE</span></span>
            <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Cuisine Raffinée</span>
          </div>
        </Link>

        <div className="flex items-center space-x-8 font-black uppercase text-xs tracking-widest text-gray-500">
          <Link to="/" className="hover:text-orange-600 transition">Accueil</Link>
          <Link to="/menu" className="hover:text-orange-600 transition">Menu</Link>

          <Link to="/panier" className="relative group flex items-center text-gray-700 hover:text-orange-600 transition">
            <div className="relative p-2">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-7 w-7" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 3h2l.4 2M7 13h10l4-8H5.4M7 13L5.4 5M7 13l-2.293 2.293c-.63.63-.184 1.707.707 1.707H17m0 0a2 2 0 100 4 2 2 0 000-4zm-8 2a2 2 0 11-4 0 2 2 0 014 0z" />
              </svg>
              {/* L-3adad l-7aqiqi dyal l-panier */}
              <span className="absolute top-0 right-0 bg-orange-600 text-white text-[10px] font-bold rounded-full h-5 w-5 flex items-center justify-center border-2 border-white">{cartCount}</span>
            </div>
            <span className="font-black ml-1 uppercase tracking-widest">Panier</span>
          </Link>
        </div>
      </div>
    </div>
  </nav>
);

// Menu Page m3a Modal d-Selection
const Menu = ({ categories, addToCart }) => {
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedDish, setSelectedDish] = useState(null); // Bach n-3rfo achmen pizza clicka 3liha
  const navigate = useNavigate();

  const handleOrderClick = (dish) => {
    setSelectedDish(dish); // Tla3 l-modal
  };

  const confirmOrder = (type) => {
    addToCart({ ...selectedDish, orderType: type });
    setSelectedDish(null);
    navigate('/panier'); // Idih nishan l-panier
  };

  const filteredItems = categories.flatMap(cat => 
    cat.dishes.map(dish => ({ ...dish, categoryName: cat.name }))
  ).filter(item => 
    item.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="min-h-screen py-20 px-6 bg-gray-50 text-center">
      <h2 className="text-5xl font-black text-gray-900 mb-12 italic uppercase tracking-tighter text-center">La Carte</h2>

      {/* Search Bar */}
      <div className="max-w-xl mx-auto mb-16 relative">
        <input 
          type="text" placeholder="Pizza, Tacos..." 
          className="w-full px-14 py-5 rounded-2xl bg-white shadow-xl border-none outline-none focus:ring-4 focus:ring-orange-100 font-bold transition"
          onChange={(e) => setSearchTerm(e.target.value)}
        />
        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 absolute left-5 top-1/2 -translate-y-1/2 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
        </svg>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-10 max-w-7xl mx-auto">
        {filteredItems.map(item => (
          <div key={item.id} className="bg-white rounded-[2.5rem] shadow-xl overflow-hidden hover:scale-105 transition duration-500 border border-gray-100">
            <div className="h-64 bg-orange-50 flex items-center justify-center text-7xl">
              {item.categoryName.toLowerCase().includes('pizza') ? '🍕' : '🌮'}
            </div>
            <div className="p-8">
              <h3 className="text-2xl font-black text-gray-800 mb-4">{item.name}</h3>
              <div className="flex items-center justify-between mt-4">
                <span className="text-2xl font-black text-green-600">{item.price} DH</span>
                <button 
                  onClick={() => handleOrderClick(item)}
                  className="bg-gray-900 text-white px-6 py-3 rounded-xl font-black text-xs uppercase hover:bg-orange-600 transition"
                >
                  Commander
                </button>
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* --- MODAL DIALOG --- */}
      {selectedDish && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-[3rem] p-10 max-w-sm w-full shadow-2xl text-center transform scale-110">
            <h3 className="text-3xl font-black text-gray-900 mb-2 italic">Excellent choix!</h3>
            <p className="text-gray-500 mb-8 font-bold uppercase text-[10px] tracking-widest">Comment voulez-vous déguster votre {selectedDish.name}?</p>

            <div className="space-y-4">
              <button 
                onClick={() => confirmOrder('Sur Place')}
                className="w-full py-5 bg-orange-600 text-white rounded-2xl font-black text-lg hover:bg-orange-700 transition shadow-lg shadow-orange-100"
              >
                🍽️ Sur Place
              </button>
              <button 
                onClick={() => confirmOrder('Emporter')}
                className="w-full py-5 bg-gray-900 text-white rounded-2xl font-black text-lg hover:bg-black transition shadow-lg"
              >
                🥡 À Emporter
              </button>
              <button 
                onClick={() => setSelectedDish(null)}
                className="w-full py-3 text-gray-400 font-bold text-xs uppercase tracking-widest"
              >
                Annuler
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

// Main App: Bach n-khzno l-cart l-foq
function App() {
  const [categories, setCategories] = useState([]);
  const [cart, setCart] = useState([]);

  useEffect(() => {
    axios.get('http://127.0.0.1:8000/api/categories/')
      .then(res => setCategories(res.data))
      .catch(err => console.error(err));
  }, []);

  const addToCart = (item) => {
    setCart([...cart, item]); // Zid l-makla f-l-list
  };

  return (
    <Router>
      <div className="min-h-screen bg-white font-sans">
        <Navbar cartCount={cart.length} />
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/menu" element={<Menu categories={categories} addToCart={addToCart} />} />
          <Route path="/panier" element={<PanierPage cart={cart} />} />
        </Routes>
      </div>
    </Router>
  );
}

